// Parse RT Planning API response (RtPlanningResult)
const result = $input.first().json;

if (!result || typeof result !== 'object') {
  return [{ json: { valid: false, missing: ['RT Planning API returned no data'], extracted: null } }];
}

if (result.error) {
  return [{ json: { valid: false, missing: ['RT Planning API error: ' + result.error], extracted: null } }];
}

// Get part info from extraction
const partNumber = result.extraction?.partNumber ?? '';
const customerName = result.extraction?.customerName
  || $('IMAP Email Trigger').first().json.from?.text
  || $('IMAP Email Trigger').first().json.from?.address
  || 'Unknown';

// Map techniqueCards → RtViewRequest[]
const rawCards = result.techniqueCards || [];
const views = rawCards.map((card, i) => ({
  viewNumber:       card.viewNumber ?? i + 1,
  shotType:         card.shotType ?? 1,
  qtyPartsPerFilm:  card.qtyPartsPerFilm ?? 1,
  filmSizeLabel:    card.filmSizeLabel || '7X17',
  unpackLoadTime:   card.unpackLoadTime ?? 5,
  darkroomSortTime: card.darkroomSortTime ?? 3,
  shotTime:         card.shotTime ?? 5,
  readTime:         card.readTime ?? 3,
}));

// Validate required fields
const missing = [];
if (!partNumber) missing.push('partNumber (could not extract from email)');
if (views.length === 0) missing.push('at least one RT view / technique card');

// Normalize filmSizeLabel format (e.g. 4x10 → 4X10)
for (const view of views) {
  if (view.filmSizeLabel) {
    view.filmSizeLabel = view.filmSizeLabel.replace(/[xX*]/, 'X').replace(/[^0-9X]/g, '');
  }
}

return [{ json: {
  valid: missing.length === 0,
  missing,
  extracted: { partNumber, customerName, views },
  planningResult: result,
  emailFrom: $('IMAP Email Trigger').first().json.from.text,
  emailMessageId: $('IMAP Email Trigger').first().json.messageId,
  emailSubject: $('IMAP Email Trigger').first().json.subject,
} }];

const quote = $('POST /api/rt/quote').first().json;
const views = quote.views || [];
const recommended = quote.selectedTier || {};
const planning = $('Validate RT Prerequisites').first().json.planningResult || {};

const rowsHtml = views.map(view => {
  return `
    <tr>
      <td>View ${view.viewNumber}</td>
      <td>${view.shotTypeLabel || view.shotType}</td>
      <td>${view.qtyPartsPerFilm}</td>
      <td>${view.filmSize ? view.filmSize.label : 'N/A'}</td>
      <td>$${(view.costs ? view.costs.pricePerView : 0).toFixed(2)}</td>
    </tr>`;
}).join('');

const tierRowsHtml = (quote.tierComparison || []).map(tier => {
  return `<tr${tier.isRecommended ? ' style="background:#e8f5e9;font-weight:bold"' : ''}>
    <td>${tier.tierLabel}${tier.isRecommended ? ' ★' : ''}</td>
    <td>$${tier.grandTotal.toFixed(2)}</td>
  </tr>`;
}).join('');

const warningsHtml = (planning.planningWarnings || []).length > 0
  ? `<h2>Planning Warnings</h2><ul>${planning.planningWarnings.map(w => `<li>${w}</li>`).join('')}</ul>`
  : '';

const techCardRows = (planning.techniqueCards || []).map(card => {
  return `<tr>
    <td>View ${card.viewNumber}</td>
    <td>${card.location || ''}</td>
    <td>${card.selectedMachineId || ''}</td>
    <td>${card.kV || '—'} kV</td>
    <td>${card.filmClass || '—'}</td>
    <td>${card.xray_wash_risk || '—'}</td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; padding: 40px; color: #222; }
  h1 { color: #1a56db; }
  h2 { color: #444; margin-top: 30px; font-size: 1em; text-transform: uppercase; letter-spacing: 1px; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th { background: #1a56db; color: white; padding: 10px; text-align: left; }
  td { padding: 10px; border-bottom: 1px solid #ddd; }
  .summary { margin-top: 20px; }
  .total { font-weight: bold; font-size: 1.3em; color: #1a56db; }
  .footer { margin-top: 40px; font-size: 0.85em; color: #888; }
</style>
</head>
<body>
<h1>NDT Radiographic Testing Quote</h1>
<p><strong>Quote #:</strong> ${quote.quoteNumber}<br>
<strong>Part Number:</strong> ${quote.partNumber}<br>
<strong>Customer:</strong> ${quote.customerName}<br>
<strong>Date:</strong> ${new Date(quote.generatedAt).toLocaleDateString()}</p>

${planning.imageQualitySummary ? `<p><em>${planning.imageQualitySummary}</em></p>` : ''}

<h2>View Breakdown</h2>
<table>
  <thead><tr><th>View</th><th>Shot Type</th><th>Parts/Film</th><th>Film Size</th><th>Price/View</th></tr></thead>
  <tbody>${rowsHtml}</tbody>
</table>

${techCardRows ? `<h2>Technique Cards</h2>
<table>
  <thead><tr><th>View</th><th>Location</th><th>Machine</th><th>kV</th><th>Film Class</th><th>Wash Risk</th></tr></thead>
  <tbody>${techCardRows}</tbody>
</table>` : ''}

<h2>Tier Pricing Options</h2>
<table>
  <thead><tr><th>Pricing Tier</th><th>Grand Total</th></tr></thead>
  <tbody>${tierRowsHtml}</tbody>
</table>

<div class="summary">
  <p>Labor: $${(quote.totals ? quote.totals.totalLabor : 0).toFixed(2)}</p>
  <p>Film: $${(quote.totals ? quote.totals.totalFilm : 0).toFixed(2)}</p>
  <p class="total">Grand Total (Recommended): $${recommended.grandTotal ? recommended.grandTotal.toFixed(2) : 'N/A'}</p>
</div>

${warningsHtml}

<div class="footer">
  <p>★ Recommended tier. Quote valid 30 days. Contact us to confirm scheduling.</p>
</div>
</body></html>`;

return [{ json: { html, quoteNumber: quote.quoteNumber, quoteId: quote.quoteId, grandTotal: recommended.grandTotal || quote.totals?.totalPrice || 0 } }];

